Compose_Task_Acknowledgement_Link.inputs:
@concat(
  'https://taskack.page.gd/index.html',
  '?item=', string(coalesce(outputs('Get_item_Task')?['body/ID'], 0)),
  '&name=', uriComponent(
    first(
      split(
        trim(replace(replace(string(coalesce(outputs('Get_item_Task')?['body/AssignedTo'], '')), '\n', ' '), '\r', ' ')),
        '@'
      )
    )
  ),
  '&email=', uriComponent(
    trim(replace(replace(string(coalesce(outputs('Get_item_Task')?['body/AssignedTo'], '')), '\n', ' '), '\r', ' '))
  ),
  '&title=', uriComponent(
    trim(replace(replace(string(coalesce(outputs('Get_item_Task')?['body/Title'], '')), '\n', ' '), '\r', ' '))
  ),
  '&ref=', uriComponent(
    concat('TASK-', string(coalesce(outputs('Get_item_Task')?['body/ID'], 0)))
  )
)

