Compose_Priority_Description.inputs:
@{if(
  or(
    contains(toLower(string(coalesce(triggerBody()?['NewActivityTask']?['Priority'], 'normal'))),'critical'),
    contains(toLower(string(coalesce(triggerBody()?['NewActivityTask']?['Priority'], 'normal'))),'urgent'),
    contains(toLower(string(coalesce(triggerBody()?['NewActivityTask']?['Priority'], 'normal'))),'high')
  ),
  'Accelerated handling is required. Please acknowledge immediately and proceed to review the linked document without delay.',
  if(
    contains(toLower(string(coalesce(triggerBody()?['NewActivityTask']?['Category'], 'general'))),'confidential'),
    'This dispatch should be handled with controlled circulation. Please open the linked document and treat it accordingly.',
    'Please review the linked document, acknowledge receipt, and proceed with the requested official action.'
  )
)}
``

Compose_Priority_Text_1.inputs:
@if(
  or(
    contains(toLower(string(coalesce(triggerBody()?['NewActivityTask']?['Priority'], 'normal'))),'critical'),
    contains(toLower(string(coalesce(triggerBody()?['NewActivityTask']?['Priority'], 'normal'))),'urgent'),
    contains(toLower(string(coalesce(triggerBody()?['NewActivityTask']?['Priority'], 'normal'))),'high')
  ),
  'Priority Review Window',
  if(
    contains(toLower(string(coalesce(triggerBody()?['NewActivityTask']?['Category'], 'general'))),'confidential'),
    'Restricted Executive Dispatch',
    'Standard Official Review'
  )
)

Compose_Handling_Status.inputs:
@if(
  contains(toLower(string(coalesce(triggerBody()?['NewActivityTask']?['Category'], 'general'))),'confidential'),
  'Restricted Circulation',
  if(
    or(
      contains(toLower(string(coalesce(triggerBody()?['NewActivityTask']?['Priority'], 'normal'))),'critical'),
      contains(toLower(string(coalesce(triggerBody()?['NewActivityTask']?['Priority'], 'normal'))),'urgent'),
      contains(toLower(string(coalesce(triggerBody()?['NewActivityTask']?['Priority'], 'normal'))),'high')
    ),
    'Expedited Review',
    'Standard Official Review'
  )
)
